  const desc = `${s.n} (${s.org}) في ${s.c}: ${s.full ? 'تمويل كامل' : 'تمويل جزئي'} لمرحلة ${lvTxt(s)}. ${s.note} الشروط والملفات المطلوبة وموعد التقديم.`.slice(0, 300);
