  const jsonld = { '@context': 'https://schema.org', '@type': 'MonetaryGrant', name: s.n, alternateName: s.org, description: s.note, url: abs(p), sameAs: s.url, funder: { '@type': 'Organization', name: s.org, url: s.url } };
